mapper.select:
update pm_webhook_outbox o
set status = 'DELIVERING',
    locked_at = #{now},
    updated_at = #{now}
from (
    select id
    from pm_webhook_outbox
    where (
        status in ('PENDING', 'RETRYING')
        and next_attempt_at <= #{now}
    ) or (
        status = 'DELIVERING'
        and locked_at <= #{lockCutoff}
    )
    order by next_attempt_at asc, id asc
    for update skip locked
    limit #{limit}
) due
where o.id = due.id
returning o.*
